import pandas as pd

def test_any_nullable_kleene_na_unobserved():
    df = pd.DataFrame(
        {
            "cat": pd.Categorical(["a", "a", "b"], categories=["a", "b", "c"]),
            "val": pd.array([False, pd.NA, True], dtype="boolean"),
        }
    )
    try:
        result = df.groupby("cat", observed=False)["val"].any()
    except Exception as exc:
        assert False, f"groupby any should not error: {exc}"
    assert result.dtype == pd.BooleanDtype(), f"expected boolean dtype, got {result.dtype}"
    assert pd.isna(result.loc["a"]), f"Kleene any of False+NA should be NA, got {result.loc['a']}"
